function fail(message: string): never {
  throw new Error(message);
}

function assertDefined<T>(value: T | undefined, name: string): T {
  if (value === undefined) fail(`${name} was undefined`);
  return value;   // ✓ compiles: control-flow knows fail() never returns
}

// Exhaustiveness guard — remember this for Lesson 5:
function handle(state: "idle" | "loading" | "error") {
  switch (state) {
    case "idle": return "Ready";
    case "loading": return "Loading…";
    case "error": return "Failed";
    default: {
      const unreachable: never = state;  // Error if a new state is ever added!
      return unreachable;
    }
  }
}

