async function withRetry<T>(
  fn: () => Promise<T>,
  attempts: number = 3,
  onRetry?: (error: unknown, attempt: number) => void
): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      lastError = e;
      onRetry?.(e, i + 1);          // optional callback, invoked if provided
    }
  }
  throw lastError;                   // control-flow: this line always throws
}

