function pipe<A, B, C>(
  f: (a: A) => B,
  g: (b: B) => C
): (a: A) => C {
  return (a) => g(f(a));
}

const double = (n: number) => n * 2;        // (a: number) => number
const show = (n: number) => `n=${n}`;        // (a: number) => string
const shout = (s: string) => s.toUpperCase(); // (a: string) => string

const f = pipe(double, show);    // ✓ (a: number) => string
const g = pipe(show, shout);     // ✓ (a: number) => string — output feeds input
const h = pipe(show, double);    // Error: string is not assignable to number
